<template><div class="page"><div class="page-header"><h2>设备接入</h2></div><el-card shadow="never"><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="conn_id" label="接入编号" width="110"/><el-table-column prop="eid" label="设备SN" width="130"/><el-table-column label="协议" width="70"><template #default="{row}"><el-tag size="small">{{ row.protocol||'MQTT' }}</el-tag></template></el-table-column><el-table-column prop="topic" label="MQTT主题" min-width="130" show-overflow-tooltip/><el-table-column label="在线状态" width="80"><template #default="{row}"><el-tag :type="onlineTag(row.online_status)" size="small">{{ row.online_status||'OFFLINE' }}</el-tag></template></el-table-column><el-table-column label="心跳间隔" width="80"><template #default="{row}">{{ row.heartbeat_interval||60 }}s</template></el-table-column><el-table-column prop="last_heartbeat" label="最后心跳" width="110"/></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="'设备接入 — '+(detail?.conn_id||'')" v-model="drawer" width="500px"><template v-if="detail"><el-descriptions :column="2" border size="small"><el-descriptions-item label="接入编号">{{ detail.conn_id }}</el-descriptions-item><el-descriptions-item label="设备SN">{{ detail.eid }}</el-descriptions-item><el-descriptions-item label="协议">{{ detail.protocol||'MQTT' }}</el-descriptions-item><el-descriptions-item label="在线状态"><el-tag :type="onlineTag(detail.online_status)" size="small">{{ detail.online_status||'OFFLINE' }}</el-tag></el-descriptions-item><el-descriptions-item label="心跳间隔">{{ detail.heartbeat_interval||60 }}秒</el-descriptions-item><el-descriptions-item label="最后心跳">{{ detail.last_heartbeat||'-' }}</el-descriptions-item><el-descriptions-item label="MQTT主题" :span="2">{{ detail.topic||'-' }}</el-descriptions-item><el-descriptions-item label="端点地址" :span="2">{{ detail.endpoint||'-' }}</el-descriptions-item></el-descriptions></template></el-dialog></div></template>
<script setup lang="ts">import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {useDetailDrawer} from '@/composables/useDetailDrawer';import {fetchDeviceConns} from '@/api/iot';import type {IotRecord} from '@/api/iot'
const{items,loading,page,perPage,total}=useListPage<IotRecord>(fetchDeviceConns);const{drawer,detail,open}=useDetailDrawer<IotRecord>()
function onlineTag(s:string){const m:Record<string,string>={ONLINE:'success',OFFLINE:'info',UNKNOWN:'warning'};return m[s]||'info'}</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}</style>
